<template>
  <section aria-label="手术受控原件与资源登记治理">
    <el-alert :closable="false" type="info" title="此处登记、审核和审计原资料；不预约资源、不写入排台、不授予患者照护或岗位资格。" />
    <p v-if="error" role="alert">{{ error }}</p>
    <el-tabs v-model="tab"><el-tab-pane label="原资料" name="sources">
      <el-form inline><el-form-item label="明确手术资源池"><el-select v-model="pool" aria-label="明确手术资源池" :disabled="!!poolId"><el-option v-for="item in options?.pools||[]" :key="item.pool_id" :value="item.pool_id" :label="item.name+' · #'+item.department_id" /></el-select></el-form-item><el-form-item label="原资料类型"><el-select v-model="sourceKind" aria-label="原资料类型"><el-option v-for="(label,key) in surgerySourceKinds" :key="key" :value="key" :label="label" /></el-select></el-form-item><el-form-item><el-button :disabled="!pool||loading" @click="load">重新读取当前目录</el-button><el-button :disabled="!mayCreate||loading" @click="beginCreate">登记明确原件草稿</el-button><el-button v-if="isSuper&&(protectedBinding||legacyScheduleId)" :disabled="loading||!protectedAvailable" @click="beginProtected">按业务原执行映射登记安全忙时</el-button></el-form-item></el-form>
      <p v-if="clinical&&!mayCreate">专业原件创建需要业务父页面明确绑定原申请，并提供当前实际医师别名；此治理入口不猜申请或签署身份。</p>
      <p v-if="pool&&!options?.pools.some(item=>item.pool_id===pool)">当前选中的是治理审计资源池；完整父范围由服务器重核。当前目录不授予新录入资格。</p>
      <el-table v-loading="loading" :data="rows" row-key="source_record_id"><el-table-column prop="source_record_id" label="原件标识" min-width="210" /><el-table-column label="原登记UTC" min-width="210"><template #default="{row}">{{ row.recorded_at }}</template></el-table-column><el-table-column label="治理状态"><template #default="{row}">{{ surgerySourceStates[row.status] }} · v{{ row.revision }}</template></el-table-column><el-table-column label="用途"><template #default="{row}">{{ row.eligible_for_new_use?'原件治理及父范围当前成立；能力/缺项另核':'当前仅定位或审计' }}</template></el-table-column><el-table-column label="操作" width="130"><template #default="{row}"><el-button size="small" @click="inspect(row)">核对完整原件</el-button></template></el-table-column></el-table>
      <el-pagination v-if="total" v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next,total" @current-change="load" />
      <article v-if="selected" aria-label="手术原件完整核对">
        <h3>{{ surgerySourceKinds[selected.source_kind] }} · {{ surgerySourceStates[selected.status] }}</h3><p>原件SHA：{{ selected.content_hash }}</p><p>治理SHA：{{ selected.governance_hash }}</p>
        <p>原登记UTC：{{ selected.recorded_at }}；原专业签署：{{ selected.professional_status }}；审核UTC：{{ selected.reviewed_at??'原无审核' }}。</p>
        <p v-if="!selected.eligible_for_new_use">当前不可作为新场景的已生效原件：{{ selected.exclusion_reasons.join('；') }}。</p>
        <p v-if="selected.payload===null">当前仅返回治理摘要，私有正文和父件已由服务器隐去；不会从旧缓存恢复。</p>
        <template v-else><p>以下为已核对完整摘要的院内原量与真实时钟。null、0、false和未知均保持原义，不代表已确认可排台。</p><el-button @click="showOriginal=!showOriginal">{{ showOriginal?'收起':'展开' }}完整院内冻结原件</el-button><el-input v-if="showOriginal" :model-value="JSON.stringify(selected,null,2)" aria-label="完整院内手术原件" type="textarea" :rows="20" readonly /></template>
        <p><el-button v-if="selected.can_review===true" @click="beginAction('publish')">审核发布本条</el-button><el-button v-if="selected.can_review===true" @click="beginAction('reject')">审核拒绝本条</el-button><el-button v-if="selected.can_revoke===true" type="danger" @click="beginAction('revoke')">按当前版本撤销本条</el-button></p>
      </article>
    </el-tab-pane><el-tab-pane v-if="isSuper" label="全局资源登记与声明" name="registry"><RegistryManager v-if="tab==='registry'" :pool-id="pool" :active="active" @registry-changed="registryChanged" @pool-selected="chooseAuditPool" @invalidate="invalidate" /></el-tab-pane></el-tabs>
    <el-dialog :model-value="creating" title="登记明确手术来源草稿" width="min(1000px,96vw)" @update:model-value="value=>!value&&closeCreate()">
      <template v-if="creating&&protectedMode"><ProtectedEditor v-if="protectedBinding" :pool-id="pool" :binding="protectedBinding" @validity="value=>draft=value" /><ProtectedMapping v-else :pool-id="pool" :legacy-schedule-id="legacyScheduleId" @validity="value=>draft=value" @invalidate="invalidate" /></template><template v-else-if="creating"><el-form-item v-if="!clinical" label="当前资源池真实物理资源"><el-select v-model="resource" aria-label="当前资源池真实物理资源"><el-option v-for="item in resources" :key="item.resource_id" :value="item.resource_id" :label="item.resource_kind+' · '+item.resource_id" /></el-select></el-form-item><SourceEditor v-if="clinical||resource" :key="sourceKind+':'+String(resource)" :kind="sourceKind" :pool-id="pool" :resource-id="resource" :application-id="applicationId" :clinical-signers="signers" @validity="value=>draft=value" /></template>
      <template #footer><el-button @click="closeCreate">关闭</el-button><el-button :disabled="!draft.valid||loading||!(protectedMode?protectedAvailable:mayCreate)" type="primary" @click="create">保存原件草稿，等待审核</el-button></template>
    </el-dialog>
    <el-dialog :model-value="!!action" title="按原版本进行独立来源治理" width="min(760px,94vw)" @update:model-value="value=>!value&&closeAction()"><p>{{ action==='revoke'?'撤销':action==='publish'?'审核发布':'审核拒绝' }} {{ selected?.source_record_id }}，预期版本 {{ selected?.revision }}。本操作不产生岗位资格、优化结果或实际排台。</p><el-input v-model="basis" aria-label="本次来源治理明确依据" type="textarea" :rows="5" placeholder="至少20个非空白字符；撤销最多1000字符，审核最多4000 UTF-8字节" /><template #footer><el-button @click="closeAction">关闭</el-button><el-button type="primary" :disabled="!(action==='revoke'?surgeryRevokeBasis(basis):surgeryBasis(basis))||loading" @click="govern">保存本次明确治理</el-button></template></el-dialog>
  </section>
</template>

<script setup>
import {computed,defineAsyncComponent,onActivated,onBeforeUnmount,onDeactivated,ref,watch} from 'vue';
import {useStore} from 'vuex';
import SourceEditor from './AISurgerySources/SourceEditor.vue';
const ProtectedEditor=defineAsyncComponent(()=>import('./AISurgerySources/ProtectedEditor.vue'));
const ProtectedMapping=defineAsyncComponent(()=>import('./AISurgerySources/ProtectedMapping.vue'));
import {supportHash,supportId,supportCanonical,supportDigest} from '@/api/inpatientSupport';
import {getSurgerySourceOptions,getSurgerySources,getSurgerySource,getCompleteSurgeryRegistry,createSurgerySource,createSurgeryProtectedCapsule,reviewSurgerySource,revokeSurgerySource,surgerySourceKinds,surgerySourceStates,surgeryRegistryKinds,surgerySourceMetadataValid,verifySurgerySource,verifySurgeryTransition,surgeryPositive,surgeryBasis,surgeryRevokeBasis} from '@/api/ai/surgerySources';
const RegistryManager=defineAsyncComponent(()=>import('./AISurgerySources/RegistryManager.vue'));
const props=defineProps({poolId:{type:String,default:null},applicationId:{type:String,default:null},clinicalSigners:{type:Array,default:null},protectedBinding:{type:Object,default:null},legacyScheduleId:{type:String,default:null},active:{type:Boolean,default:true}}),emit=defineEmits(['source-changed','invalidate']);
const store=useStore(),options=ref(null),pool=ref(null),sourceKind=ref('resource_availability_busy'),rows=ref([]),total=ref(0),page=ref(1),selected=ref(null),showOriginal=ref(false),loading=ref(false),error=ref(''),creating=ref(false),protectedMode=ref(false),resources=ref([]),resource=ref(null),draft=ref({valid:false,request:null}),action=ref(null),basis=ref(''),tab=ref('sources');let epoch=0,alive=true,suppressScope=false,wasDeactivated=false;
const roles=computed(()=>store.getters['user/permissions']||[]),isSuper=computed(()=>roles.value.includes('super_admin')),clinical=computed(()=>['case_requirements','duration_observation','case_duration_estimate'].includes(sourceKind.value)),signers=computed(()=>{const actual=options.value?.clinical_signers??[];return props.clinicalSigners===null?actual:actual.filter(d=>props.clinicalSigners.some(p=>p.doctor_id===d.doctor_id&&p.name===d.name&&p.department_id===d.department_id));});
const mayCreate=computed(()=>!!options.value?.pools.some(p=>p.pool_id===pool.value)&&(clinical.value?supportId(props.applicationId)&&signers.value.length>0:options.value.can_record_operational===true));
const protectedAvailable=computed(()=>isSuper.value&&!!options.value?.pools.some(p=>p.pool_id===pool.value)&&(props.protectedBinding?supportId(props.protectedBinding.legacy_schedule_id)&&supportId(props.protectedBinding.resource_id)&&(props.legacyScheduleId===null||props.legacyScheduleId===props.protectedBinding.legacy_schedule_id):supportId(props.legacyScheduleId)));
function boundary(){return JSON.stringify([store.state.user.accessToken,roles.value,pool.value,sourceKind.value,props.active,props.applicationId,props.clinicalSigners,props.protectedBinding,props.legacyScheduleId]);}
function ticket(){return{epoch:++epoch,boundary:boundary()};}function current(t){return alive&&props.active&&!!store.state.user.accessToken&&t.epoch===epoch&&t.boundary===boundary();}
function clear(){epoch++;rows.value=[];total.value=0;selected.value=null;showOriginal.value=false;loading.value=false;error.value='';closeCreate();closeAction();}
function invalidate(){clear();emit('invalidate');}
function closeCreate(){epoch++;loading.value=false;creating.value=false;protectedMode.value=false;resource.value=null;resources.value=[];draft.value={valid:false,request:null};}function closeAction(){action.value=null;basis.value='';}
function failed(t,failure){if(!current(t))return;clear();error.value=failure?.message||'原手术资料或当前授权不可用';emit('invalidate');}
function optionsValid(value){return value&&Array.isArray(value.pools)&&value.pools.every(p=>supportId(p.pool_id)&&surgeryPositive(p.department_id)&&typeof p.name==='string'&&supportHash(p.content_hash)&&supportHash(p.governance_hash))&&Array.isArray(value.source_kinds)&&value.source_kinds.length===Object.keys(surgerySourceKinds).length&&new Set(value.source_kinds).size===value.source_kinds.length&&value.source_kinds.every(k=>Object.hasOwn(surgerySourceKinds,k))&&Array.isArray(value.registry_kinds)&&value.registry_kinds.length===Object.keys(surgeryRegistryKinds).length&&new Set(value.registry_kinds).size===value.registry_kinds.length&&value.registry_kinds.every(k=>Object.hasOwn(surgeryRegistryKinds,k))&&[value.can_record_operational,value.has_actual_doctor,value.can_manage_registry,value.can_review].every(v=>typeof v==='boolean')&&value.provider_required===false&&Array.isArray(value.clinical_signers)&&value.clinical_signers.every(d=>surgeryPositive(d.doctor_id)&&typeof d.name==='string'&&(d.department_id===null||surgeryPositive(d.department_id)));}
async function initialize(){clear();options.value=null;if(!props.active||!store.state.user.accessToken)return;const t=ticket();loading.value=true;try{const data=(await getSurgerySourceOptions()).data;if(!current(t))return;if(!optionsValid(data))throw new Error('来源目录与当前完整类型或真实医师别名不一致');if(props.poolId!==null&&!supportId(props.poolId))throw new Error('业务原资源池标识无效');suppressScope=true;options.value=data;if(props.poolId)pool.value=props.poolId;else if(pool.value&&!data.pools.some(p=>p.pool_id===pool.value))pool.value=null;if(!data.can_record_operational&&data.has_actual_doctor&&!clinical.value)sourceKind.value='case_requirements';suppressScope=false;if(pool.value)await load();}catch(failure){suppressScope=false;failed(t,failure);}finally{if(current(t))loading.value=false;}}
async function load(){selected.value=null;showOriginal.value=false;closeCreate();closeAction();if(!supportId(pool.value)){rows.value=[];total.value=0;return;}const t=ticket();loading.value=true;try{const data=(await getSurgerySources(sourceKind.value,{pool_id:pool.value,page:page.value,page_size:20})).data;if(!current(t))return;if(!data||!Array.isArray(data.items)||!Number.isSafeInteger(data.total)||data.total<0||data.page!==page.value||data.page_size!==20||data.items.length>20||!data.items.every(row=>surgerySourceMetadataValid(row,sourceKind.value,pool.value)))throw new Error('来源定位目录与当前资源池或完整治理状态不一致');rows.value=data.items;total.value=data.total;}catch(failure){failed(t,failure);}finally{if(current(t))loading.value=false;}}
async function inspect(row){const t=ticket();selected.value=null;showOriginal.value=false;closeAction();loading.value=true;try{const data=(await getSurgerySource(sourceKind.value,row.source_record_id)).data;if(!current(t))return;if(data?.source_record_id!==row.source_record_id||data.content_hash!==row.content_hash||!await verifySurgerySource(data,sourceKind.value,pool.value))throw new Error('完整来源正文或当前父范围与所选原件不一致');if(current(t))selected.value=data;}catch(failure){failed(t,failure);}finally{if(current(t))loading.value=false;}}
async function beginCreate(){if(!mayCreate.value)return;closeCreate();if(!clinical.value){const t=ticket();loading.value=true;try{const data=await getCompleteSurgeryRegistry('resource',{pool_id:pool.value});if(!current(t))return;if(data.some(r=>!supportId(r.resource_id)||!['room','person','equipment'].includes(r.resource_kind)||r.eligible_for_new_use!==true))throw new Error('当前物理资源候选包含失效或不明确的原件');resources.value=data;}catch(failure){failed(t,failure);return;}finally{if(current(t))loading.value=false;}}creating.value=true;}
function beginProtected(){if(!protectedAvailable.value)return;closeCreate();protectedMode.value=true;creating.value=true;}
async function create(){if(!(protectedMode.value?protectedAvailable.value:mayCreate.value)||!draft.value.valid)return;const protectedRequest=protectedMode.value;const body=JSON.parse(JSON.stringify(draft.value.request)),t=ticket();loading.value=true;try{const data=(await(protectedRequest?createSurgeryProtectedCapsule(body):createSurgerySource(sourceKind.value,body))).data;if(!current(t))return;if(data?.status!=='draft'||data.revision!==1||!await verifySurgerySource(data,protectedRequest?'resource_availability_busy':sourceKind.value,pool.value)||protectedRequest&&(data.pool_id!==body.pool_id||data.resource_id!==body.resource_id||data.payload.record_type!=='busy_capsule'||data.payload.basis_code!=='protected_legacy_witness'||data.payload.basis_hash!==await supportDigest({basis_code:'explicit_legacy_utc_interpretation',basis_note:body.clock_basis_note})||['start_at','end_at','end_absent_reason','verified_until_at','continuity_status','transition_class_key','transition_class_absent_reason','accounting'].some(key=>supportCanonical(data.payload[key])!==supportCanonical(body[key]))))throw new Error('新原件草稿未返回自身一致的完整原件');if(!current(t))return;closeCreate();selected.value=data;rows.value=[data];total.value=1;emit('source-changed',{source_record_id:data.source_record_id,pool_id:data.pool_id,source_kind:data.source_kind});}catch(failure){failed(t,failure);}finally{if(current(t))loading.value=false;}}
function beginAction(value){if(!selected.value||(value==='revoke'?selected.value.can_revoke!==true:selected.value.can_review!==true))return;action.value=value;basis.value='';}
async function govern(){const original=selected.value,value=action.value;if(!original||!(value==='revoke'?surgeryRevokeBasis(basis.value):surgeryBasis(basis.value))||value==='revoke'&&original.can_revoke!==true||value!=='revoke'&&original.can_review!==true)return;const body={expected_revision:original.revision,expected_content_hash:original.content_hash,basis_note:basis.value,...(value==='revoke'?{}:{decision:value})},t=ticket();loading.value=true;try{const data=(await(value==='revoke'?revokeSurgerySource:reviewSurgerySource)(sourceKind.value,original.source_record_id,body)).data;if(!current(t))return;if(!await verifySurgerySource(data,sourceKind.value,pool.value)||!await verifySurgeryTransition(data,original,value,body))throw new Error('本次治理回执与原ID、原版本、完整原件或明确依据不一致');if(!current(t))return;closeAction();showOriginal.value=false;selected.value=data;rows.value=rows.value.map(row=>row.source_record_id===data.source_record_id?data:row);emit('source-changed',{source_record_id:data.source_record_id,pool_id:data.pool_id,source_kind:data.source_kind});}catch(failure){failed(t,failure);}finally{if(current(t))loading.value=false;}}
function chooseAuditPool(value){if(!isSuper.value||!supportId(value?.pool_id))return;tab.value='sources';if(pool.value===value.pool_id)load();else pool.value=value.pool_id;page.value=1;}
function registryChanged(value){emit('source-changed',value);initialize();}
watch([()=>store.state.user.accessToken,()=>JSON.stringify(roles.value),()=>props.active,()=>props.poolId,()=>props.applicationId,()=>JSON.stringify(props.clinicalSigners),()=>JSON.stringify(props.protectedBinding),()=>props.legacyScheduleId],()=>{invalidate();initialize();},{flush:'sync',immediate:true});
watch([pool,sourceKind],()=>{if(suppressScope)return;clear();page.value=1;emit('invalidate');if(options.value)load();},{flush:'sync'});
onActivated(()=>{if(wasDeactivated){wasDeactivated=false;initialize();}});onDeactivated(()=>{wasDeactivated=true;options.value=null;invalidate();});onBeforeUnmount(()=>{alive=false;options.value=null;invalidate();});
</script>

<style scoped>
section{min-width:0}p{line-height:1.7;overflow-wrap:anywhere}article{margin-top:20px;border:1px solid #dcdfe6;padding:16px}.el-pagination{margin:12px 0}.el-select{min-width:240px}
</style>
